<?php
declare(strict_types=1);
namespace SitePilot\Skills;

/**
 * Validates a WooCommerce product plan generated by AI.
 * Returns a list of errors (empty = valid).
 */
final class ProductPlanValidator {

	/**
	 * Validate a product plan array against the schema.
	 *
	 * @param array $plan The AI-generated product plan.
	 * @return array{ok:bool, errors:string[]}
	 */
	public function validate( array $plan ): array {
		$errors = array();

		// Required: name.
		if ( empty( $plan['name'] ) || ! is_string( $plan['name'] ) ) {
			$errors[] = __( 'Product name is required.', 'sitepilot-ai' );
		} elseif ( mb_strlen( $plan['name'] ) > 255 ) {
			$errors[] = __( 'Product name is too long (max 255 chars).', 'sitepilot-ai' );
		}

		// Type (default: simple).
		$type = $plan['type'] ?? 'simple';
		if ( ! in_array( $type, ProductPlanSchema::ALLOWED_TYPES, true ) ) {
			$errors[] = sprintf(
				__( 'Invalid product type "%s". Allowed: simple, variable, grouped, external.', 'sitepilot-ai' ),
				$type
			);
		}

		// Price validation.
		if ( ! empty( $plan['price'] ) && ! preg_match( '/^[0-9]+(\.[0-9]{1,2})?$/', $plan['price'] ) ) {
			$errors[] = __( 'Price must be a valid number (e.g. 29.99).', 'sitepilot-ai' );
		}
		if ( ! empty( $plan['regular_price'] ) && ! preg_match( '/^[0-9]+(\.[0-9]{1,2})?$/', $plan['regular_price'] ) ) {
			$errors[] = __( 'Regular price must be a valid number.', 'sitepilot-ai' );
		}
		if ( ! empty( $plan['sale_price'] ) && ! preg_match( '/^[0-9]+(\.[0-9]{1,2})?$/', $plan['sale_price'] ) ) {
			$errors[] = __( 'Sale price must be a valid number.', 'sitepilot-ai' );
		}

		// Status.
		$status = $plan['status'] ?? 'draft';
		if ( ! in_array( $status, ProductPlanSchema::ALLOWED_STATUSES, true ) ) {
			$errors[] = sprintf(
				__( 'Invalid status "%s". Allowed: draft, pending, publish.', 'sitepilot-ai' ),
				$status
			);
		}

		// Stock status.
		if ( ! empty( $plan['stock_status'] ) && ! in_array( $plan['stock_status'], ProductPlanSchema::ALLOWED_STOCK, true ) ) {
			$errors[] = sprintf(
				__( 'Invalid stock status "%s". Allowed: instock, outofstock, onbackorder.', 'sitepilot-ai' ),
				$plan['stock_status']
			);
		}

		// Stock quantity.
		if ( isset( $plan['stock_quantity'] ) && ( ! is_int( $plan['stock_quantity'] ) || $plan['stock_quantity'] < 0 ) ) {
			$errors[] = __( 'Stock quantity must be a non-negative integer.', 'sitepilot-ai' );
		}

		// Categories.
		if ( ! empty( $plan['categories'] ) && ! is_array( $plan['categories'] ) ) {
			$errors[] = __( 'Categories must be an array of IDs.', 'sitepilot-ai' );
		}

		return array(
			'ok'     => empty( $errors ),
			'errors' => $errors,
		);
	}

	/**
	 * Sanitize a product plan for safe storage/execution.
	 *
	 * @return array
	 */
	public function sanitize( array $plan ): array {
		return array(
			'name'              => sanitize_text_field( $plan['name'] ?? '' ),
			'description'       => wp_kses_post( $plan['description'] ?? '' ),
			'short_description' => wp_kses_post( $plan['short_description'] ?? '' ),
			'price'             => $this->sanitize_price( $plan['price'] ?? '' ),
			'regular_price'     => $this->sanitize_price( $plan['regular_price'] ?? '' ),
			'sale_price'        => $this->sanitize_price( $plan['sale_price'] ?? '' ),
			'categories'        => array_map( 'absint', (array) ( $plan['categories'] ?? array() ) ),
			'tags'              => array_map( 'absint', (array) ( $plan['tags'] ?? array() ) ),
			'status'            => in_array( $plan['status'] ?? 'draft', ProductPlanSchema::ALLOWED_STATUSES, true ) ? $plan['status'] : 'draft',
			'stock_status'      => in_array( $plan['stock_status'] ?? 'instock', ProductPlanSchema::ALLOWED_STOCK, true ) ? $plan['stock_status'] : 'instock',
			'stock_quantity'    => absint( $plan['stock_quantity'] ?? 0 ),
			'manage_stock'      => ! empty( $plan['manage_stock'] ),
			'type'              => in_array( $plan['type'] ?? 'simple', ProductPlanSchema::ALLOWED_TYPES, true ) ? $plan['type'] : 'simple',
			'image_url'         => esc_url_raw( $plan['image_url'] ?? '' ),
			'sku'               => sanitize_text_field( $plan['sku'] ?? '' ),
			'weight'            => sanitize_text_field( $plan['weight'] ?? '' ),
			'dimensions'        => array(
				'length' => sanitize_text_field( $plan['dimensions']['length'] ?? '' ),
				'width'  => sanitize_text_field( $plan['dimensions']['width'] ?? '' ),
				'height' => sanitize_text_field( $plan['dimensions']['height'] ?? '' ),
			),
		);
	}

	private function sanitize_price( string $price ): string {
		$price = str_replace( ',', '.', $price );
		if ( preg_match( '/^[0-9]+(\.[0-9]{1,2})?$/', $price ) ) {
			return $price;
		}
		return '';
	}
}
